L7_1 = "\229\176\145\227\129\151\233\169\154\227\129\132\227\129\159\227\129\170\227\128\130\233\187\146\230\157\177\227\129\174\230\150\176\227\129\151\227\129\132\233\150\128\228\184\187\227\128\129\232\161\128\233\172\188\227\129\175\227\131\160\227\130\173\227\131\160\227\130\173\227\129\168\227\129\151\227\129\159\229\183\168\228\186\186\227\129\160\227\129\168\232\129\158\227\129\132\227\129\166\227\129\132\227\129\159\227\129\145\227\129\169\227\128\129\227\129\147\227\130\147\227\129\170\231\190\142\229\176\145\229\165\179\227\129\160\227\129\163\227\129\159\227\129\168\227\129\175\227\128\130"
L6_1.m_Talk_JPN = L7_1
L7_1 = "I'm a little surprised. I heard that the new sect leader of Black East, who went by the name Bloodseeker, would be this burly giant. I didn't expect it would be a pretty girl."
