L7_1 = "T\195\180i h\198\161i ng\225\186\161c nhi\195\170n. T\195\180i nghe n\195\179i th\225\187\167 l\196\169nh m\225\187\155i t\195\170n Huy\225\186\191t Qu\225\187\183 c\225\187\167a Black East, s\225\186\189 l\195\160 ng\198\176\225\187\157i kh\225\187\149ng l\225\187\147 v\225\186\161m v\225\187\161 c\198\161. Nh\198\176ng kh\195\180ng ng\225\187\157 l\225\186\161i l\195\160 m\225\187\153t c\195\180 g\195\161i xinh \196\145\225\186\185p."
L6_1.m_Talk_VTN = L7_1
L7_1 = "\230\136\145\230\156\137\228\186\155\229\144\131\230\131\138\227\128\130\230\136\145\229\144\172\232\175\180\233\187\145\228\184\156\228\184\128\232\132\137\231\154\132\230\150\176\230\142\140\233\151\168\232\161\128\233\172\188\230\152\175\228\184\170\228\186\148\229\164\167\228\184\137\231\178\151\231\154\132\229\183\168\228\186\186\239\188\140\228\189\134\230\178\161\230\131\179\229\136\176\229\141\180\230\152\175\232\191\153\230\160\183\231\154\132\231\190\142\229\176\145\229\165\179\227\128\130"
L6_1.m_Talk_SCN = L7_1
L7_1 = "Ich bin ein wenig \195\188berrascht. Ich habe geh\195\182rt, dass die neue Sektenf\195\188hrerin des Schwarzen Ostens, die den Namen \226\128\158Blutsucherin\226\128\156 tr\195\164gt, ein st\195\164mmiger Riese sein w\195\188rde. Ich h\195\164tte nicht erwartet, dass es so ein h\195\188bsches M\195\164dchen sein w\195\188rde."
L6_1.m_Talk_DEU = L7_1
L7_1 = "Mais j\226\128\153avoue que je suis un peu surpris. Je croyais que la nouvelle suzeraine de l\226\128\153Ouest Obscur, Traquesang, \195\169tait une cr\195\169ature g\195\169ante et monstrueuse. Pas un canon de beaut\195\169 comme toi."
L6_1.m_Talk_FRA = L7_1
